import React from 'react';
import * as icons from '..';
import type { BrandIconType } from '../../types';

interface BrandIconTypeDemo extends BrandIconType {
  iconName: keyof typeof icons;
}

const Demo = ({ size = 'sm', iconName }: BrandIconTypeDemo) => {
  const Icon = icons[iconName];
  return <Icon size={size} />;
};

export default Demo;
